function harbourFish(c) {
  // A continuous belly, head and tail; the eye is a generous knockout.
  c.save(); c.translate(40, 0);
  c.beginPath(); c.moveTo(32, -32); c.lineTo(57, -20);
  c.bezierCurveTo(78, -42, 105, -37, 120, -11);
  c.bezierCurveTo(104, 14, 77, 17, 57, -3);
  c.lineTo(32, 9); c.lineTo(39, -11); c.closePath(); c.fill();
  c.save(); c.globalCompositeOperation = 'destination-out';
  c.beginPath(); c.arc(102, -14, 3.3, 0, Math.PI * 2); c.fill(); c.restore(); c.restore();
}
